CREATE TABLE dbo.test_product_price_units(id int NOT NULL PRIMARY KEY,label nvarchar(20) NOT NULL, factor decimal(28,8) NOT NULL,origin_product_id bigint NOT NULL,unit_proof_hash char(64) NOT NULL,CONSTRAINT CK_c09_price_units CHECK(id>0 AND label=N'ADET' AND factor=1));
CREATE TABLE dbo.test_product_price_scope(type nvarchar(20) NOT NULL,unit_id int NULL,tier int NOT NULL,currency nvarchar(3) NOT NULL,CONSTRAINT CK_c09_price_scope CHECK((type=N'purchase' AND unit_id IS NULL AND tier=0) OR(type=N'sale' AND unit_id IS NOT NULL AND unit_id>0 AND tier BETWEEN 1 AND 6)),CONSTRAINT CK_c09_price_currency CHECK(currency IN(N'TRY',N'USD',N'EUR')));
CREATE UNIQUE INDEX UX_c09_price_scope ON dbo.test_product_price_scope(type,unit_id,tier,currency);
CREATE TABLE dbo.test_product_price_current(id bigint NOT NULL PRIMARY KEY,product_id bigint NOT NULL,type nvarchar(20) NOT NULL,unit_id int NULL,tier int NOT NULL,currency nvarchar(3) NOT NULL,native_price_id bigint NOT NULL UNIQUE,version_id bigint NOT NULL,row_version rowversion NOT NULL,CONSTRAINT CK_c09_price_current CHECK(product_id=301986 AND id=native_price_id));
CREATE UNIQUE INDEX UX_c09_price_current_tuple ON dbo.test_product_price_current(product_id,type,unit_id,tier,currency);
CREATE TABLE dbo.test_product_price_versions(id bigint IDENTITY NOT NULL PRIMARY KEY,price_id bigint NOT NULL,price_exact decimal(28,8) NULL,actor_id bigint NOT NULL,reason nvarchar(500) NOT NULL,created_at datetime2(3) NOT NULL,request_id uniqueidentifier NOT NULL UNIQUE,CONSTRAINT CK_c09_price_version CHECK(actor_id=16 AND(price_exact IS NULL OR price_exact>=0) AND LEN(LTRIM(RTRIM(reason)))>=3));
CREATE TABLE dbo.test_product_price_requests(request_id uniqueidentifier NOT NULL PRIMARY KEY,actor_id bigint NOT NULL,payload_json nvarchar(max) NOT NULL,payload_hash char(64) NOT NULL,before_json nvarchar(max) NOT NULL,before_revision char(64) NOT NULL,state nvarchar(12) NOT NULL,native_price_id bigint NULL,version_id bigint NULL,after_json nvarchar(max) NULL,after_revision char(64) NULL,response_json nvarchar(max) NULL,created_at datetime2(3) NOT NULL,completed_at datetime2(3) NULL,CONSTRAINT CK_c09_price_request_actor CHECK(actor_id=16),CONSTRAINT CK_c09_price_request_json CHECK(ISJSON(payload_json)=1 AND ISJSON(before_json)=1 AND(after_json IS NULL OR ISJSON(after_json)=1) AND(response_json IS NULL OR ISJSON(response_json)=1)),CONSTRAINT CK_c09_price_request_state CHECK((state=N'reserved' AND after_json IS NULL AND after_revision IS NULL AND response_json IS NULL AND completed_at IS NULL) OR(state=N'completed' AND native_price_id IS NOT NULL AND version_id IS NOT NULL AND after_json IS NOT NULL AND after_revision IS NOT NULL AND response_json IS NOT NULL AND completed_at IS NOT NULL)));
CREATE TABLE dbo.test_product_price_manifest(name sysname NOT NULL PRIMARY KEY,definition_hash char(64) NOT NULL);
INSERT dbo.test_product_price_units SELECT TOP(1) CONVERT(int,s.main_unit_source_id),N'ADET',CAST(1 AS decimal(28,8)),s.origin_product_id,s.product_binding_hash FROM dbo.test_purchase_fx_sources s WHERE s.unit=N'ADET' AND s.unit_factor=1 ORDER BY s.main_unit_source_id,s.origin_product_id;
IF (SELECT COUNT(*) FROM dbo.test_product_price_units)<>1 THROW 51097,'C09_UNIT_SOURCE_REQUIRED',1;
INSERT dbo.test_product_price_scope SELECT N'purchase',NULL,0,currency FROM dbo.test_purchase_fx_rates;
INSERT dbo.test_product_price_scope SELECT N'sale',u.id,t.tier,r.currency FROM dbo.test_product_price_units u CROSS JOIN(VALUES(1),(2),(3),(4),(5),(6))t(tier) CROSS JOIN dbo.test_purchase_fx_rates r;
EXEC sys.sp_executesql N'CREATE TRIGGER dbo.c09_immutable_test_product_price_units ON dbo.test_product_price_units WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM deleted) OR EXISTS(SELECT 1 FROM inserted) THROW 51097,''C09_PRICE_HISTORY_IMMUTABLE'',1; END;'; INSERT dbo.test_product_price_manifest VALUES(N'c09_immutable_test_product_price_units',N'EF3250868470E47F1C312707A9EB8ACEEA5352EAFBEF95ACC5C7CAC215D43C8C');
